functions.parse:
program_t parse(const char *path)
{
    parser_t *p = parser_new(256);
    parser_result_t result;
    if (parser_load_file(p, path) != 0)
    {
        fprintf(stderr, "Error: Failed to open file '%s'\n", path);
        exit(1);
    }
    result = parser_parse(p);
    if (result.err != PARSER_OK)
    {
        fprintf(stderr, "Error at %s:%zu:%zu: %s\n", result.path, result.row, result.col,
                parser_err_to_cstr(result.err));
        exit(1);
    }
    parser_destroy(p);
    return result.prog;
}

