           "Options:\n"
           "  -h, --help    Show the usage\n",
           path);
}

functions.main:
int main(int argc, const char **argv)
{
    if (argc != 2)
    {
        fprintf(stderr, "Error: No file provided\n");
        fprintf(stderr, "Try '%s -h'\n", argv[0]);
        return 1;
    }
    else if (strcmp(argv[1], "-h") == 0 || strcmp(argv[1], "--help") == 0)
    {
        usage(argv[0]);
        return 0;
    }
    program_t prog = parse(argv[1]);
    env_t *e = env_new(1024, 32);
    runtime_result_t result = env_run(e, &prog);
    if (result.err != RUNTIME_OK)
    {
        fprintf(stderr, "Error at %s:%zu:%zu: %s\n", result.em->path, result.em->row, result.em->col,
                runtime_err_to_cstr(result.err));
        exit(1);
    }
    env_destroy(e);
    program_destroy(&prog);
    return result.ex;
}

